CREATE POLICY "Own game images read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'game-images' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Own game images insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'game-images' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Own game images update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'game-images' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Own game images delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'game-images' AND (storage.foldername(name))[1] = auth.uid()::text);